**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("siatka.txt");
    int m[5][5];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];
    bool horiz = true;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 5; j++)
            if (m[i][j] != m[4 - i][j]) horiz = false;
    cout << "Symetria pozioma: " << (horiz ? "TAK" : "NIE") << endl;
    bool vert = true;
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 2; j++)
            if (m[i][j] != m[i][4 - j]) vert = false;
    cout << "Symetria pionowa: " << (vert ? "TAK" : "NIE") << endl;
    int pal = 0;
    for (int i = 0; i < 5; i++) {
        bool ok = true;
        for (int j = 0; j < 2; j++)
            if (m[i][j] != m[i][4 - j]) ok = false;
        if (ok) pal++;
    }
    cout << "Wiersze palindromy: " << pal << endl;
    return 0;
}
```

Weryfikacja:
- Pozioma: wiersz 0=[1,0,1,0,0]=wiersz 4, wiersz 1=[0,1,0,1,1]=wiersz 3 → TAK
- Pionowa: kol 0=[1,0,1,0,1] vs kol 4=[0,1,1,1,0] → rozne → NIE
- Palindromy: tylko wiersz 2=[1,0,0,0,1] czytany od lewej=od prawej → 1
